function evidence = f90_xauto11_extract_candidate_evidence( ...
        modelPath, outputDir)
%F90_XAUTO11_EXTRACT_CANDIDATE_EVIDENCE Replay with verified inputs.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end
[taskRoot, sharedRoot, publicOutputRoot] = localRoots("F90-XAUTO-11");
addpath(sharedRoot, "-begin");
addpath(publicOutputRoot, "-begin");
cleanup = onCleanup(@()localRemovePaths(sharedRoot, publicOutputRoot)); %#ok<NASGU>
official = jsondecode(fileread(simuverity_official_scenarios_path()));
spec = struct( ...
    "schema", "simuverity.formal90-xauto11-evidence.v1", ...
    "task_id", "F90-XAUTO-11", ...
    "scenarios", official.scenarios, ...
    "output_contract", localOutputs, ...
    "input_builder", @localInputs, ...
    "requested_input_builder", @localRequested, ...
    "stop_time", @(~,~)double(official.simulation.duration_seconds), ...
    "postprocess", @localPostprocess, ...
    "static_audit", @localAudit, ...
    "evidence_sample_s", ...
        double(official.simulation.evidence_grid_step_seconds));
evidence = f90_xauto11_candidate_simulation( ...
    modelPath, outputDir, spec);
evidence = localFinalize(evidence, outputDir);
end

function rows = localOutputs
rows = localRows(["suspension_state", "active_control_state"], [5 2]);
end

function inputs = localInputs(scenario, ~)
inputs = struct("xauto11_input", struct( ...
    "sprung_mass_kg", double(scenario.sprung_mass_kg), ...
    "suspension_stiffness_n_per_m", ...
        double(scenario.suspension_stiffness_n_per_m), ...
    "suspension_damping_n_s_per_m", ...
        double(scenario.suspension_damping_n_s_per_m), ...
    "road_peak_m", double(scenario.road_peak_m), ...
    "road_angular_frequency_rad_per_s", ...
        double(scenario.road_angular_frequency_rad_per_s)));
end

function requested = localRequested(scenario, ~)
inputs = localInputs(scenario, []);
requested = inputs.xauto11_input;
end

function row = localPostprocess(row, outputs, ~, ~)
t = double(outputs.time_s(:));
state = double(outputs.suspension_state);
control = double(outputs.active_control_state);
road = state(:,1);
body = state(:,2);
wheel = state(:,3);
deflection = state(:,4);
acceleration = state(:,5);
command = control(:,1);
force = control(:,2);
tail = t >= 1.5;
row.metrics = struct( ...
    "peak_road_displacement_m", max(abs(road)), ...
    "peak_body_displacement_m", max(abs(body)), ...
    "peak_wheel_displacement_m", max(abs(wheel)), ...
    "peak_suspension_deflection_m", max(abs(deflection)), ...
    "rms_suspension_deflection_m", sqrt(mean(deflection.^2)), ...
    "peak_body_acceleration_m_per_s2", max(abs(acceleration)), ...
    "rms_body_acceleration_m_per_s2", sqrt(mean(acceleration.^2)), ...
    "tail_rms_body_acceleration_m_per_s2", ...
        sqrt(mean(acceleration(tail).^2)), ...
    "tail_rms_suspension_deflection_m", ...
        sqrt(mean(deflection(tail).^2)), ...
    "peak_controller_normalized_command", max(abs(command)), ...
    "rms_controller_normalized_command", sqrt(mean(command.^2)), ...
    "peak_applied_active_force_n", max(abs(force)), ...
    "rms_applied_active_force_n", sqrt(mean(force.^2)), ...
    "command_force_correlation", abs(localCorrelation(command, force)), ...
    "all_finite", all(isfinite([state(:); control(:)])));
row.outputs = outputs;
row.offline_metrics = row.metrics;
row.valid = row.output_contract.all_required_pass && ...
    row.metrics.all_finite && numel(t) >= 100 && ...
    abs(t(1)) <= 1e-9 && abs(t(end) - 2.0) <= 1e-6;
end

function log = localLog(time, data, channels, units)
log = struct("format", "Timeseries", "time", time', "data", data, ...
    "channels", {channels}, "units", {units});
end

function value = localCorrelation(left, right)
left = left - mean(left);
right = right - mean(right);
denominator = sqrt(sum(left.^2) * sum(right.^2));
if denominator <= 1e-15
    value = 0.0;
else
    value = sum(left .* right) / denominator;
end
end

function audit = localAudit(model, spec)
structure = simuverity_candidate_structure( ...
    model, string({spec.output_contract.name})');
audit = struct( ...
    "block_count", structure.block_count, ...
    "dynamic_block_count", structure.dynamic_block_count, ...
    "physical_connection_block_count", ...
        structure.physical_connection_block_count, ...
    "signal_cycle_observed", structure.signal_cycle_present, ...
    "connected_public_output_count", structure.connected_output_count, ...
    "qualification_basis", ...
        "candidate topology and published output bindings");
end

function evidence = localFinalize(evidence, outputDir)
rows = evidence.scenarios;
for index = 1:numel(rows)
    rows(index).input = rows(index).requested_inputs;
    t = double(rows(index).outputs.time_s(:));
    rows(index).logs = struct( ...
        "suspension_state", localLog( ...
            t, double(rows(index).outputs.suspension_state), ...
            {"road_displacement_m", "body_displacement_m", ...
             "wheel_displacement_m", "suspension_deflection_m", ...
             "body_acceleration_m_per_s2"}, ...
            {"m", "m", "m", "m", "m/s^2"}), ...
        "active_control_state", localLog( ...
            t, double(rows(index).outputs.active_control_state), ...
            {"controller_normalized_command", ...
             "applied_active_force_n"}, {"1", "N"}));
end
evidence.scenarios = rows;
evidence.evaluation_subject = "candidate";
evidence.simulate_pass = ~isempty(rows) && ...
    all([rows.simulation_pass]);
evidence.all_scenarios_valid = ~isempty(rows) && ...
    all([rows.valid]);
evidence.runtime_model_unchanged = evidence.binding_preserved;
evidence.EVIDENCE_COMPLETE = logical(evidence.score_inputs_valid && ...
    evidence.input_application_all_pass && ...
    evidence.input_application_representations_unique);
evidence.evidence_complete = evidence.EVIDENCE_COMPLETE;
evidence.scenario_count = numel(rows);
localWriteJson(fullfile(outputDir, "evidence.json"), evidence);
end

function rows = localRows(names, widths)
rows = repmat(struct( ...
    "name", "", "evidence_name", "", "width", 0, ...
    "interpolation", "linear"), numel(names), 1);
for index = 1:numel(names)
    rows(index).name = names(index);
    rows(index).evidence_name = names(index);
    rows(index).width = widths(index);
end
end

function [taskRoot, sharedRoot, publicOutputRoot] = localRoots(taskId)
scriptRoot = fileparts(mfilename("fullpath"));
tasksRoot = fileparts(scriptRoot);
sharedRoot = fullfile(tasksRoot, "_shared");
repoRoot = tasksRoot;
for index = 1:3, repoRoot = fileparts(repoRoot); end
taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
publicOutputRoot = fullfile(repoRoot, "scripts", "unified", ...
    "public_output");
end

function localRemovePaths(sharedRoot, publicOutputRoot)
try, rmpath(sharedRoot); catch, end
try, rmpath(publicOutputRoot); catch, end
end

function localWriteJson(path, value)
temporary = string(path) + ".staging-" + ...
    string(java.util.UUID.randomUUID);
fid = fopen(temporary, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:F90:XAUTO11:Write", ...
    "Cannot write candidate evidence.");
cleanup = onCleanup(@()fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, PrettyPrint=true), "char");
clear cleanup
assert(movefile(temporary, path, "f"), ...
    "SimuVerity:F90:XAUTO11:Publish", ...
    "Cannot publish candidate evidence.");
end
